import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    // Caches for procedural background elements
    private starsCache: HTMLCanvasElement | null = null;
    private mountainsCache: HTMLCanvasElement | null = null;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.6, scene.background); // Keep top dark longer
        bgGrad.addColorStop(1, scene.horizon); // Fade to horizon color
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            // General Stars for non-river scenes
            this.drawStaticStars(ctx, w, h, 80);
        }

        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            // Default Mountains
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // C. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.6)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.5;
            const alpha = Math.random() * 0.5 + 0.1;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        // Nebula band
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.1)'); // Indigo
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.15)'); // Violet
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.1)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        // Dense Stars in River
        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        // Far Layer
        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        // Near Layer
        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                // Smooth sine waves for dunes
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING (Per Frame) ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Horizon Glow Pulse
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 2. Feature Specifics
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 3. Fog Clouds (Foreground Atmosphere)
        this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);

            // Wavy lines
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            const hue = (t * 10 + i * 30) % 360;
            // Aurora colors: Green -> Teal -> Purple
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6; // Slight sway
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        // Heat distortion bands (Simulated)
        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        // Ensure identity transform before drawing screen-space clouds
        ctx.setTransform(1, 0, 0, 1, 0, 0); 

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }
}

import { VFXStateManager } from "./state";

export class VFXAmbience {
    private timer: number = 0;

    public update(dt: number, type: string, state: VFXStateManager) {
        if (type === 'NONE') return;

        this.timer += dt;
        // Snow and Ash should be dense, others sparse
        const rate = (type === 'SNOW' || type === 'ASH') ? 0.03 : 0.15; 

        if (this.timer > rate) {
            this.timer = 0;
            // Spawn across the screen
            const x = Math.random() * 1600 - 200;
            const y = Math.random() * 1000 - 200;

            const p = state.getParticle();
            p.x = x; p.y = y; 
            // Randomize Z for parallax feeling (doesn't affect render order in VFX system much, but physics uses it)
            p.z = Math.random() * 400 + 50; 
            p.type = 'ATMOSPHERE'; 

            if (type === 'SNOW') {
                p.color = '#fff';
                p.size = Math.random() * 2.5 + 1.5;
                p.vx = 40 + Math.random() * 30; // Wind
                p.vy = 80 + Math.random() * 40; // Fall
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'ASH') {
                p.color = Math.random() > 0.5 ? '#1c1917' : '#451a03'; // Dark Ash
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 30 + Math.random() * 20;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.color = Math.random() > 0.5 ? '#f59e0b' : '#ef4444';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 40;
                p.vy = -40 - Math.random() * 30; // Rise
                p.life = 2.5; p.maxLife = 2.5;
                p.blendMode = 'screen'; 
            } else if (type === 'SPORES') {
                // Mystic floaty particles
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2.5 + 0.5;
                p.vx = (Math.random() - 0.5) * 15;
                p.vy = (Math.random() - 0.5) * 15;
                p.life = 6.0; p.maxLife = 6.0;
                p.blendMode = 'screen';
            }

            state.particles.push(p);
        }
    }
}

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() { this.cache.clear(); }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE', 'DEBRIS', 'SHARD'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE', 'ATMOSPHERE'].includes(type)) type = 'GLOW_SPRITE';

        const key = `T92_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);
        const r = 40; 

        switch (type) {
            case 'SMOKE': ParticlePainter.drawSmoke(ctx, r, color); break;
            case 'GLOW_SPRITE': ParticlePainter.drawAtmosphere(ctx, r, color); break;
            case 'SPIKE':
            case 'SPARK': ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color); break;
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_LOCK': IconPainter.drawHexLock(ctx, r, color); break;
            case 'SHADOW_BLOB':
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, color); 
                grad.addColorStop(0.6, 'rgba(0,0,0,0.3)');
                grad.addColorStop(1, 'transparent'); 
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
                break;
            case 'CRACKS': ParticlePainter.drawCracks(ctx, r, color); break;
            case 'SLASH': ParticlePainter.drawSlash(ctx, r, color); break;
            case 'BEAM':
                const beamGrad = ctx.createLinearGradient(0, -60, 0, 60);
                beamGrad.addColorStop(0, 'transparent');
                beamGrad.addColorStop(0.2, color);
                beamGrad.addColorStop(0.8, color);
                beamGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = beamGrad;
                ctx.fillRect(-10, -60, 20, 120);
                break;
            default:
                // Fallback for missing textures (Magenta Square for debug)
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-5,-5,10,10);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('GLOW_SPRITE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }
    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const key = `DETAIL_${type}_${color}_${variant}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(HEX_SIZE * 2, HEX_SIZE * 2);
        ctx.translate(HEX_SIZE, HEX_SIZE);

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.3;

        if (type === 'FOREST') {
            ctx.beginPath();
            ctx.moveTo(0, -10);
            ctx.lineTo(8, 5);
            ctx.lineTo(-8, 5);
            ctx.closePath();
            ctx.fill();
        } else if (type === 'VOID') {
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                const angle = i * Math.PI / 2;
                ctx.moveTo(0,0);
                ctx.lineTo(Math.cos(angle)*8, Math.sin(angle)*8);
            }
            ctx.strokeStyle = color;
            ctx.stroke();
        }

        this.cache.set(key, canvas);
        return canvas;
    }
}

