import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.6, scene.background); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 80);
        }

        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // C. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.6)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.5;
            const alpha = Math.random() * 0.5 + 0.1;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.1)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.15)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.1)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 2. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 3. Fog
        this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        // REMOVED: ctx.setTransform(1, 0, 0, 1, 0, 0) - This was causing HiDPI scaling issues

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { HazardPainter } from "./grid/painters/HazardPainter"; 
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;

        ctx.resetTransform(); 

        // Fallback Fill: If background renderer fails, at least show a dark void, not transparency
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, physicalWidth, physicalHeight);

        ctx.scale(dpr, dpr);

        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    break;
                case RenderOpType.HAZARD: 
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}
